const DAY = 24 * 3600 * 1000;
const now = Date.now();
const tsOf = (r) => {
  const t = Date.parse(r.receivedAt || r.createdAt || '');
  return Number.isFinite(t) ? t : 0;
};
const bool = (v) => v === true || v === 'true';
const rows = $input.all().map((i) => i.json).filter((r) => r && r.category && r.source !== 'eval' && now - tsOf(r) < DAY);
if (rows.length === 0) return [];
const count = (arr, key) => arr.reduce((m, r) => {
  const v = r[key] || 'unknown';
  m[v] = (m[v] || 0) + 1;
  return m;
}, {});
const ORDER = { urgent: 0, high: 1, normal: 2, low: 3 };
const mail = rows.filter((r) => r.source === 'gmail' || r.source === 'seed');
const playground = rows.filter((r) => r.source === 'playground');
const needs = rows
  .filter((r) => bool(r.needsHuman))
  .sort((a, b) => (ORDER[a.priority] ?? 9) - (ORDER[b.priority] ?? 9))
  .slice(0, 12)
  .map((r) => ({ source: r.source, category: r.category, priority: r.priority, summary: String(r.summary || '').slice(0, 160), reason: String(r.humanReason || '').slice(0, 120), from: r.fromDomain || '', subject: String(r.subject || '').slice(0, 100) }));
const stats = {
  total: rows.length,
  gmail: mail.length,
  playground: playground.length,
  byCategory: count(rows, 'category'),
  byPriority: count(rows, 'priority'),
  needsHuman: rows.filter((r) => bool(r.needsHuman)).length,
  injectionFlagged: rows.filter((r) => bool(r.injectionSuspected)).length,
  draftsCreated: rows.filter((r) => bool(r.draftCreated)).length,
  unclassified: rows.filter((r) => Number(r.confidence) <= 0).length
};
return [{ json: { stats, needs, llmInput: JSON.stringify({ stats, needsHumanItems: needs.map((n) => ({ category: n.category, priority: n.priority, summary: n.summary, reason: n.reason })) }) } }];

const base = $('Build Stats').first().json;
const s = base.stats;
const ai = $input.first().json;
const summary = typeof ai.text === 'string' && ai.text.trim() ? ai.text.trim() : 'AI summary unavailable today (the model could not be reached). The numbers below are still accurate.';
const fmt = (o) => Object.keys(o).map((k) => k.replace(/_/g, ' ') + ' ' + o[k]).join(', ');
const lines = [];
lines.push(summary, '');
lines.push('Last 24 hours: ' + s.total + ' emails (' + s.gmail + ' from Gmail, ' + s.playground + ' from the website playground)');
lines.push('By priority: ' + fmt(s.byPriority));
lines.push('By category: ' + fmt(s.byCategory));
lines.push('Needs a person: ' + s.needsHuman + ' | Injection attempts flagged: ' + s.injectionFlagged + ' | Drafts waiting in Gmail: ' + s.draftsCreated);
if (s.unclassified > 0) lines.push('Could not be classified (AI model unavailable): ' + s.unclassified);
if (base.needs.length) {
  lines.push('', 'Needs a person first:');
  base.needs.forEach((n) => lines.push('- [' + n.priority + '] ' + n.category.replace(/_/g, ' ') + ': ' + (n.summary || n.reason) + (n.source === 'playground' ? ' (playground)' : '')));
}
lines.push('', 'Nothing was sent to customers. Drafts stay in Gmail until you send them.');
const d = new Date().toISOString().slice(0, 10);
return [{ json: { subject: '[Support triage] Daily digest ' + d + ': ' + s.total + ' emails, ' + s.needsHuman + ' need a person', text: lines.join('\n') } }];
